// Extract descriptions from Groq response
const response = $input.item.json;
const content = response.choices[0].message.content;

// Get user data from webhook
const webhookData = $('Keep User Details').first().json;

// Split into individual descriptions
const descriptions = content.split('\n').filter(line => line.trim().length > 10).slice(0, 2);

// Get property data from previous node
const propertyData = $('Parse RapidAPI Data').first().json;

// Map each image to its description
const imageData = propertyData.images.map((imageUrl, index) => ({
  imageUrl,
  description: descriptions[index] || 'Beautiful property feature',
  index
}));

return imageData.map(item => ({
  ...propertyData,
  currentImage: [item.imageUrl],  // ✅ Make it an array
  // OR keep as string here but fix in the Create kie.ai Task node
  currentImage: item.imageUrl,
  currentDescription: item.description,
  imageIndex: item.index,
  // CRITICAL: Pass user data forward
  name: webhookData.name,
  email: webhookData.email
}));

// Get the output from the kie.ai task creation
const inputData = $input.item.json;

// Check if the API call was successful and data exists
if (inputData.code !== 200 || !inputData.data || !inputData.data.taskId) {
  // If the API failed (e.g., Code 500, or no taskId), throw an error
  // to stop processing this item. You can add more complex error handling later.
  throw new Error(`Kie.ai task creation failed. Code: ${inputData.code}, Msg: ${inputData.msg || 'Unknown API Error'}`);
}

// Get the data that was passed to the kie.ai task
const propertyData = $('Prepare Image Data').item.json;

return {
  taskId: inputData.data.taskId, // This is now safe to access
  imageUrl: propertyData.currentImage,
  description: propertyData.currentDescription,
  imageIndex: propertyData.imageIndex,
  // Pass ALL property data forward
  address: propertyData.address,
  price: propertyData.price,
  beds: propertyData.beds,
  baths: propertyData.baths,
  sqft: propertyData.sqft,
  name: propertyData.name,
  email: propertyData.email
};

// Extract video URL from kie.ai response
const resultJson = JSON.parse($input.item.json.data.resultJson);
const videoUrl = resultJson.resultUrls[0];

// Get all the data from the node *before* the "Check Status"
const previousData = $('Store Task Info').item.json;

return {
  videoUrl: videoUrl,
  imageUrl: previousData.imageUrl,
  description: previousData.description,
  imageIndex: previousData.imageIndex,
  // Pass ALL property data forward
  address: previousData.address,
  price: previousData.price,
  beds: previousData.beds,
  baths: previousData.baths,
  sqft: previousData.sqft,
  name: previousData.name,
  email: previousData.email,
  gdriveFileId: previousData.gdriveFileId // <-- ADD THIS LINE
};

// Organize all video clips and get GDrive IDs
const videos = items.map(item => ({
  videoUrl: item.json.videoUrl,
  description: item.json.description,
  imageIndex: item.json.imageIndex,
  gdriveFileId: item.json.gdriveFileId // <-- ADD THIS LINE
})).sort((a, b) => a.imageIndex - b.imageIndex);

// Get property data from the first item
const firstItem = items[0].json;

return {
  success: true,
  property: {
    address: firstItem.address,
    price: firstItem.price,
    beds: firstItem.beds,
    baths: firstItem.baths,
    sqft: firstItem.sqft,
    name: firstItem.name,
    email: firstItem.email
  },
  videos: videos,
  gdriveFileIds: videos.map(v => v.gdriveFileId), // <-- ADD THIS ARRAY
  videoCount: videos.length,
  cost: {
    total: videos.length * 0.15,
    perVideo: 0.15,
    breakdown: {
      animation: videos.length * 0.15,
      script: 0.00,
      total: videos.length * 0.15
    }
  },
  processingTime: new Date().toISOString()
};

